.docudesk-dashboard-widget[data-v-521cdd5c] {
	display: flex;
	flex-direction: column;
	height: 100%;
	padding: 0;
}

/* Results table */
.results-area[data-v-521cdd5c] {
	flex: 1;
	overflow-y: auto;
	padding: 0 8px;
}
.results-table[data-v-521cdd5c] {
	width: 100%;
	border-collapse: collapse;
	font-size: 0.85rem;
}
.results-table th[data-v-521cdd5c] {
	text-align: left;
	font-weight: 600;
	padding: 4px 6px;
	border-bottom: 1px solid var(--color-border);
	color: var(--color-text-maxcontrast);
	font-size: 0.8rem;
	white-space: nowrap;
}
.results-table td[data-v-521cdd5c] {
	padding: 4px 6px;
	border-bottom: 1px solid var(--color-border-dark, var(--color-border));
	vertical-align: middle;
}
.col-file[data-v-521cdd5c] {
	max-width: 140px;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}
.col-number[data-v-521cdd5c] {
	text-align: center;
	width: 60px;
}
.col-action[data-v-521cdd5c] {
	text-align: right;
	width: 80px;
	white-space: nowrap;
}
.file-link[data-v-521cdd5c] {
	color: var(--color-primary);
	text-decoration: none;
}
.file-link[data-v-521cdd5c]:hover {
	text-decoration: underline;
}
.download-link[data-v-521cdd5c] {
	color: var(--color-success);
	text-decoration: none;
	font-weight: 500;
}
.download-link[data-v-521cdd5c]:hover {
	text-decoration: underline;
}
.status-clean[data-v-521cdd5c] {
	color: var(--color-text-maxcontrast);
	font-style: italic;
}
.status-error[data-v-521cdd5c] {
	color: var(--color-error);
	cursor: help;
}
.status-label[data-v-521cdd5c] {
	color: var(--color-text-maxcontrast);
}

/* Upload area */
.upload-area[data-v-521cdd5c] {
	padding: 12px;
}
.upload-area.compact[data-v-521cdd5c] {
	padding: 6px 12px 8px;
}
.drop-zone[data-v-521cdd5c] {
	width: 100%;
	border: 2px dashed var(--color-border);
	border-radius: var(--border-radius-large);
	padding: 16px 12px;
	text-align: center;
	cursor: pointer;
	transition: border-color 0.2s, background-color 0.2s;
}
.upload-area.compact .drop-zone[data-v-521cdd5c] {
	padding: 8px 12px;
	display: flex;
	align-items: center;
	justify-content: center;
	gap: 8px;
}
.upload-area.compact .drop-text[data-v-521cdd5c] {
	margin: 0;
}
.drop-zone[data-v-521cdd5c]:hover,
.drop-zone.dragging[data-v-521cdd5c] {
	border-color: var(--color-primary);
	background-color: var(--color-primary-element-light);
}
.drop-text[data-v-521cdd5c] {
	margin: 4px 0 0 0;
	color: var(--color-text-maxcontrast);
	font-size: 0.85rem;
}
.file-input[data-v-521cdd5c] {
