	padding: 8px;
	border-top: 1px solid var(--color-border);
	color: var(--color-text-maxcontrast);
	font-size: 0.85rem;
	text-decoration: none;
}
.widget-footer[data-v-521cdd5c]:hover {
	background-color: var(--color-background-hover);
	color: var(--color-main-text);
}
